<script setup>
import { ref, watch, nextTick, onBeforeUnmount } from 'vue'
import { X, Camera } from 'lucide-vue-next'
import { effectiveDishes } from '../cookingJournal.js'
const props=defineProps({journal:{type:Object,required:true},record:{type:Object,default:null}})
const emit=defineEmits(['close','cook'])
const dialog=ref(),current=ref(null),editing=ref(false),confirmWithdraw=ref(false),history=ref([]),selectedKey=ref(''),historyIndex=ref(0),busy=ref(false),localError=ref('')
let focusBefore=null,detailEpoch=0
const safely=async fn=>{localError.value='';try{return await fn()}catch(e){localError.value=e.message}}
watch(()=>props.record,async record=>{const e=++detailEpoch;current.value=record?JSON.parse(JSON.stringify(record)):null;editing.value=false;confirmWithdraw.value=false;history.value=[];selectedKey.value='';await nextTick();if(e!==detailEpoch)return;if(record&&!dialog.value.open){focusBefore=document.activeElement;dialog.value.showModal()}else if(!record&&dialog.value.open)dialog.value.close()})
function close(){detailEpoch++;dialog.value?.close();emit('close');focusBefore?.focus?.()}
onBeforeUnmount(()=>{detailEpoch++;focusBefore?.focus?.()})
async function save(){await safely(async()=>{const r=current.value;const updated=await props.journal.patch({title:r.title,note:r.note,cooked_on:r.cooked_on,dishes:r.dishes.map(d=>({id:d.id,outcome:d.outcome,note:d.note,photos:d.photos}))},r.id);if(updated){current.value=JSON.parse(JSON.stringify(updated));editing.value=false;await props.journal.refresh()}})}
async function showHistory(dish){const e=detailEpoch;selectedKey.value=dish.dish_key;busy.value=true;await safely(async()=>{const result=await props.journal.history(dish.dish_key);if(e===detailEpoch){history.value=result;historyIndex.value=Math.max(0,result.findIndex(r=>r.id===current.value.id))}});if(e===detailEpoch)busy.value=false}
function historyDish(){return history.value[historyIndex.value]?.dishes.find(d=>d.dish_key===selectedKey.value)}
async function again(dish){await safely(async()=>{await props.journal.start({manual_name:'继续练习',dish_key:dish.dish_key});close();emit('cook')})}
async function upload(event,dish){const files=[...event.target.files];event.target.value='';for(const file of files){if(dish.photos.length>=12)break;await safely(async()=>{const url=await props.journal.uploadPhoto(file);if(url&&current.value?.dishes.some(d=>d.id===dish.id))dish.photos.push(url)})}}
async function withdraw(){await safely(async()=>{await props.journal.withdraw(current.value.id,current.value.version);close()})}
</script>
<template><dialog ref="dialog" class="kj kj-detail" @cancel.prevent="close" @click="event=>{if(event.target===dialog)close()}"><template v-if="current"><header class="kj-detail-head"><div><span class="kj-eyebrow">厨房足迹 {{ String(current.number).padStart(3,'0') }} · {{ current.cooked_on }}</span><h2>{{ current.title||'这一餐的烟火' }}</h2></div><button aria-label="关闭记录详情" @click="close"><X :size="20" /></button></header><p v-if="localError||journal.error" class="kj-error" role="alert">{{ localError||journal.error }}</p><div v-if="journal.conflict" class="kj-actions"><button @click="safely(async()=>{const r=await journal.resolveConflict('reload');if(r)current=JSON.parse(JSON.stringify(r))})">放弃本次输入，恢复服务端版本</button><button @click="safely(async()=>{const r=await journal.resolveConflict('retry');if(r)current=JSON.parse(JSON.stringify(r))})">保留输入并重试</button></div><div v-if="editing" class="kj-form-row"><label>这一餐的名字<input v-model="current.title" maxlength="80" /></label><label>日期<input v-model="current.cooked_on" type="date" /></label></div><article v-for="dish in current.dishes" :key="dish.id" class="kj-detail-dish"><div class="kj-spread"><h3>{{ dish.snapshot.name }}</h3><span class="kj-outcome-tag">{{ {success:'做成了',practice:'还想再练',skipped:'这次没做',pending:'待确认'}[dish.outcome] }}</span></div><select v-if="editing" v-model="dish.outcome" :aria-label="dish.snapshot.name+'的结果'"><option value="success">做成了</option><option value="practice">还想再练</option><option value="skipped">这次没做</option></select><div v-if="dish.photos.length" class="kj-detail-photos"><figure v-for="(url,index) in dish.photos" :key="url"><img :src="url" :alt="`${dish.snapshot.name}的成品照片${index+1}`" /><button v-if="editing" @click="dish.photos.splice(index,1)">移除这张</button></figure></div><div v-else class="kj-word-art kj-word-small"><span>{{ dish.snapshot.name }}</span><small>这次没有拍照，文字也能留下味道。</small></div><label v-if="editing">留给下次的自己<textarea v-model="dish.note" maxlength="1000" /></label><p v-else class="kj-own-note">{{ dish.note||'这一道，没有留下心得。' }}</p><label v-if="editing" class="kj-upload"><Camera :size="18" /> 添加我的成品照<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="!!journal.uploading||dish.photos.length>=12" @change="upload($event,dish)" /></label><div class="kj-actions" v-if="!editing&&['success','practice'].includes(dish.outcome)"><button @click="showHistory(dish)">看看这道菜的历次尝试</button><button @click="again(dish)">再做一次 →</button></div></article><label v-if="editing">关于这一餐<textarea v-model="current.note" maxlength="1000" /></label><p v-else class="kj-own-note">{{ current.note }}</p><section v-if="selectedKey" class="kj-history kj-paper" aria-live="polite"><h3>一道菜，几次烟火</h3><p v-if="busy">正在翻找以前的记录…</p><template v-else-if="history.length"><div class="kj-actions"><button @click="historyIndex=0" :aria-pressed="historyIndex===0">第一次</button><button @click="historyIndex=Math.max(0,history.findIndex(r=>r.id===current.id)-1)">上一次</button><button @click="historyIndex=Math.max(0,history.findIndex(r=>r.id===current.id))">这一次</button></div><label>全部尝试<select v-model.number="historyIndex"><option v-for="(r,index) in history" :key="r.id" :value="index">{{ r.cooked_on }} · 第 {{ index+1 }} 次</option></select></label><p>{{ history[historyIndex].cooked_on }} · {{ historyDish()?.outcome==='success'?'做成了':'还想再练' }}</p><div class="kj-detail-photos"><img v-for="url in historyDish()?.photos" :key="url" :src="url" alt="这次尝试的真实成品照" /></div><p v-if="!historyDish()?.photos.length" class="kj-muted">这一次没有拍照。</p><p class="kj-own-note">{{ historyDish()?.note||'这次没有留下心得。' }}</p></template></section><footer class="kj-detail-footer"><template v-if="editing"><button class="kj-primary" :disabled="journal.saving||!!journal.uploading||!effectiveDishes(current).length" @click="save">{{ journal.uploading?'照片上传中…':'保存修改' }}</button><button @click="current=JSON.parse(JSON.stringify(record));editing=false">取消编辑</button></template><template v-else><button @click="editing=true">编辑这一餐</button><button @click="confirmWithdraw=true">撤回误记</button></template><div v-if="confirmWithdraw" class="kj-withdraw-confirm" role="alert"><p>撤回后这餐将从足迹和成长统计中移除，不能恢复。确认是误记吗？</p><button class="kj-primary" @click="withdraw">确认撤回这一餐</button><button @click="confirmWithdraw=false">保留记录</button></div></footer></template></dialog></template>
